import { UsersView } from "@/components/users-view";

export default function Page() {
  return <UsersView />;
}

"use client";

import { useState } from "react";
import { usersFromParams, usersToParams } from "./admin-filters";
import { AdminUserDetail } from "./admin-user-detail";
import { AdminUsersTable } from "./admin-users-table";
import { users } from "./mock-users";
import { useUrlState } from "./use-url-state";
import { useUsersTable } from "./use-users-table";

/**
 * The users view on its own: the table, and the record page a name opens.
 *
 * admin-01 does not render this — its `admin-page.tsx` owns the URL for every
 * section at once. It ships through the `users-01` registry item, which
 * installs these same files without the sidebar, overview or payments, and
 * it lives here so both items are built from one source.
 *
 * The URL carries the users query only (search, filters, sort, page), with no
 * `view` key: this view is the whole page.
 */
export function UsersView() {
  const table = useUsersTable();
  const [openUserId, setOpenUserId] = useState<string | null>(null);

  useUrlState(
    (params) => table.restore(usersFromParams(params)),
    usersToParams(table.query)
  );

  const openUser = openUserId
    ? (users.find((user) => user.id === openUserId) ?? null)
    : null;

  // `invitedBy` holds the inviter's id, so the record can link to them.
  const inviter = openUser?.invitedBy
    ? (users.find((user) => user.id === openUser.invitedBy) ?? null)
    : null;

  return (
    <div className="flex min-w-0 flex-1 flex-col gap-6 p-4 md:p-6">
      {openUser ? (
        <AdminUserDetail
          inviter={inviter}
          onBack={() => setOpenUserId(null)}
          onOpenUser={setOpenUserId}
          user={openUser}
        />
      ) : (
        <AdminUsersTable
          onOpenUser={setOpenUserId}
          table={table}
          users={users}
        />
      )}
    </div>
  );
}

"use client";

import { Badge } from "@keystoneui/react/badge";
import { Button } from "@keystoneui/react/button";
import { Card, CardContent } from "@keystoneui/react/card";
import { Checkbox } from "@keystoneui/react/checkbox";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@keystoneui/react/dropdown-menu";
import {
  SelectionBar,
  SelectionBarButton,
  SelectionBarClose,
  SelectionBarGroup,
  SelectionBarLabel,
} from "@keystoneui/react/selection-bar";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@keystoneui/react/table";
import {
  TablePagination,
  TablePaginationButtons,
  TablePaginationControls,
  TablePaginationInfo,
  TablePaginationPageSize,
  TablePaginationStatus,
} from "@keystoneui/react/table-pagination";
import {
  Copy as CopyIcon,
  Download as DownloadIcon,
  Eye as EyeIcon,
  Hash as HashIcon,
  Ellipsis as MoreHorizontalIcon,
} from "lucide-react";
import { type ReactNode, useState } from "react";
import {
  defaultDirection,
  hasActiveFilters,
  PAGE_SIZES,
  STATUS_VARIANT,
  toUsersCsv,
  type UserSortKey,
} from "./admin-filters";
import { AdminUsersToolbar } from "./admin-users-toolbar";
import { downloadCsv } from "./csv";
import { FilteredEmpty } from "./filtered-empty";
import { statusLabels, type User } from "./mock-users";
import { ResultSummary } from "./result-summary";
import { SkeletonRows } from "./skeleton-rows";
import { SortableHead } from "./sort-menu";
import type { UserColumnId, UsersTableState } from "./use-users-table";

interface UserColumn {
  cell: (row: User, onOpenUser: (id: string) => void) => ReactNode;
  /** Classes for the body cell. */
  className?: string;
  /** Classes for the header cell — a fixed width, say. */
  headClassName?: string;
  /** Hideable from the Columns menu. The name column is not: it is the row. */
  id: UserColumnId | "name";
  label: ReactNode;
  /** The name the Columns menu shows, when `label` is not plain text. */
  menuLabel: string;
  numeric?: boolean;
  /** Present on the columns that sort. */
  sortKey?: UserSortKey;
}

const COLUMNS: readonly UserColumn[] = [
  {
    cell: (row) => (
      <span className="font-mono text-muted-foreground text-xs">{row.id}</span>
    ),
    // Explicit width: the table distributes free space, and an id needs only
    // enough room for its own text — matching `tickets-01`'s ID column.
    headClassName: "w-[116px]",
    id: "id",
    label: (
      <>
        <HashIcon className="size-3.5 shrink-0" />
        ID
      </>
    ),
    menuLabel: "ID",
    sortKey: "id",
  },
  {
    cell: (row, onOpenUser) => (
      <div className="min-w-0">
        <button
          className="cursor-pointer rounded-sm text-left font-medium hover:underline focus-visible:outline-2 focus-visible:outline-ring/50 focus-visible:outline-offset-2"
          onClick={() => onOpenUser(row.id)}
          type="button"
        >
          {row.name}
        </button>
        <div className="truncate text-muted-foreground text-xs">
          {row.email}
        </div>
      </div>
    ),
    id: "name",
    label: "User",
    menuLabel: "User",
    sortKey: "name",
  },
  {
    cell: (row) => row.role,
    className: "text-muted-foreground",
    id: "role",
    label: "Role",
    menuLabel: "Role",
    sortKey: "role",
  },
  {
    cell: (row) => row.seats,
    id: "seats",
    label: "Seats",
    menuLabel: "Seats",
    numeric: true,
    sortKey: "seats",
  },
  {
    cell: (row) => row.lastActive,
    className: "text-muted-foreground",
    id: "lastActive",
    label: "Last active",
    menuLabel: "Last active",
    sortKey: "lastActive",
  },
  {
    cell: (row) => (
      <Badge variant={STATUS_VARIANT[row.status]}>
        {statusLabels[row.status]}
      </Badge>
    ),
    id: "status",
    label: "Status",
    menuLabel: "Status",
  },
];

const USER_COLUMNS = COLUMNS.flatMap((column) =>
  column.id === "name" ? [] : [{ id: column.id, label: column.menuLabel }]
);

/**
 * The users table, on the payments table's design: the same toolbar, header,
 * skeleton, empty state, footer and selection bar, over different columns.
 * What is particular to users is the two-line name cell, and that a name opens
 * a full record page rather than a side panel — a user is a record you work
 * in, a payment one you glance at.
 */
export function AdminUsersTable({
  onOpenUser,
  table,
  users,
}: {
  onOpenUser: (id: string) => void;
  table: UsersTableState;
  /**
   * Every user the table was built from. A selection outlives filters and
   * pages, so the selection bar resolves its ids against these rather than
   * against the rows on show.
   */
  users: readonly User[];
}) {
  const { loading, result, selected } = table;
  const visible = COLUMNS.filter(
    (column) => column.id === "name" || !table.hiddenColumns.has(column.id)
  );
  const allOnPageSelected =
    result.page.length > 0 && result.page.every((row) => selected.has(row.id));

  return (
    <>
      {/* A real `h1`, above the card rather than inside it. `CardTitle` renders
          a div, so this section had no heading outline at all, and a title in
          the card made the panel announce itself rather than the page. */}
      <div className="flex w-full flex-col gap-6">
        <h1 className="font-semibold text-2xl tracking-tight">Users</h1>

        <Card variant="outline">
          <CardContent className="flex flex-col gap-4">
            <AdminUsersToolbar columns={USER_COLUMNS} table={table} />

            <Table aria-busy={loading} hoverable>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-10">
                    <Checkbox
                      aria-label="Select all users on this page"
                      checked={allOnPageSelected}
                      disabled={loading}
                      onCheckedChange={(checked) =>
                        table.togglePage(checked === true)
                      }
                    />
                  </TableHead>
                  {visible.map((column) =>
                    column.sortKey ? (
                      <SortableHead
                        className={column.headClassName}
                        columnKey={column.sortKey}
                        defaultDirection={defaultDirection}
                        key={column.id}
                        numeric={column.numeric}
                        onSortChange={table.setSort}
                        sort={table.sort}
                      >
                        {column.label}
                      </SortableHead>
                    ) : (
                      // Not sortable, so no `sortDirection` at all — see
                      // `SortableHead`.
                      <TableHead
                        className={column.headClassName}
                        key={column.id}
                        numeric={column.numeric}
                      >
                        {column.label}
                      </TableHead>
                    )
                  )}
                  {/* One icon wide, so no visible label: "Actions" above it
                      would size the column from the header. */}
                  <TableHead className="w-12">
                    <span className="sr-only">Actions</span>
                  </TableHead>
                </TableRow>
              </TableHeader>

              <TableBody>
                {loading ? (
                  <SkeletonRows
                    checkbox
                    columns={visible.length}
                    count={result.page.length || table.pageSize}
                    twoLine={visible.findIndex(
                      (column) => column.id === "name"
                    )}
                  />
                ) : null}
                {!loading && result.page.length === 0 ? (
                  <FilteredEmpty
                    colSpan={visible.length + 2}
                    filtered={hasActiveFilters(table.filters)}
                    noun="users"
                    onClear={table.clearFilters}
                  />
                ) : null}
                {loading
                  ? null
                  : result.page.map((row) => (
                      <TableRow
                        className="group/row"
                        data-state={
                          selected.has(row.id) ? "selected" : undefined
                        }
                        key={row.id}
                      >
                        <TableCell>
                          <Checkbox
                            aria-label={`Select ${row.name}`}
                            checked={selected.has(row.id)}
                            onCheckedChange={() => table.toggleRow(row.id)}
                          />
                        </TableCell>
                        {visible.map((column) => (
                          <TableCell
                            className={column.className}
                            data-column={column.id}
                            key={column.id}
                            numeric={column.numeric}
                          >
                            {column.cell(row, onOpenUser)}
                          </TableCell>
                        ))}
                        <TableCell>
                          <UserRowActions
                            name={row.name}
                            onOpen={() => onOpenUser(row.id)}
                            userId={row.id}
                          />
                        </TableCell>
                      </TableRow>
                    ))}
              </TableBody>
            </Table>

            {/* Composed: the info slot's only props-driven content is a
                selection count, which the `SelectionBar` already states. */}
            <TablePagination
              pageCount={result.pageCount}
              pageIndex={table.pageIndex}
            >
              <TablePaginationInfo>
                <ResultSummary
                  noun={["user", "users"]}
                  pageIndex={table.pageIndex}
                  pageSize={table.pageSize}
                  rowCount={result.page.length}
                  totalCount={result.total}
                />
              </TablePaginationInfo>
              <TablePaginationControls>
                <TablePaginationPageSize
                  onValueChange={table.setPageSize}
                  options={PAGE_SIZES}
                  value={table.pageSize}
                />
                <TablePaginationStatus
                  pageCount={result.pageCount}
                  pageIndex={table.pageIndex}
                />
                <TablePaginationButtons
                  onPageIndexChange={table.setPageIndex}
                  pageCount={result.pageCount}
                  pageIndex={table.pageIndex}
                />
              </TablePaginationControls>
            </TablePagination>
          </CardContent>
        </Card>
      </div>

      <UserSelectionBar
        onClear={table.clearSelection}
        selected={selected}
        users={users}
      />
    </>
  );
}

/**
 * The same two actions as the payments bar, for the same reason: this block
 * can perform them. Role changes, invites and suspensions need a backend, and
 * buttons that do nothing were what this bar used to carry.
 */
function UserSelectionBar({
  onClear,
  selected,
  users,
}: {
  onClear: () => void;
  selected: ReadonlySet<string>;
  users: readonly User[];
}) {
  const [copied, setCopied] = useState(false);
  const rows = users.filter((user) => selected.has(user.id));

  return (
    <SelectionBar open={selected.size > 0}>
      <SelectionBarClose onClick={onClear} />
      <SelectionBarGroup>
        <SelectionBarLabel>
          {selected.size} {selected.size === 1 ? "user" : "users"} selected
        </SelectionBarLabel>
      </SelectionBarGroup>
      <SelectionBarButton
        onClick={() => downloadCsv("users-selected.csv", toUsersCsv(rows))}
      >
        <DownloadIcon />
        Export
      </SelectionBarButton>
      <SelectionBarButton
        onClick={async () => {
          try {
            await navigator.clipboard.writeText(
              rows.map((row) => row.id).join("\n")
            );
            setCopied(true);
            setTimeout(() => setCopied(false), 1500);
          } catch {
            // Insecure context or permission denied; nothing to undo.
          }
        }}
      >
        <CopyIcon />
        {copied ? "Copied" : "Copy IDs"}
      </SelectionBarButton>
    </SelectionBar>
  );
}

/**
 * Row actions, in a trailing menu rather than a hover-revealed button.
 *
 * The button it replaces was unreachable on touch — `focus-visible` rescues a
 * keyboard, not a finger. The name stays clickable, so opening a record keeps
 * its one-click path.
 */
function UserRowActions({
  name,
  onOpen,
  userId,
}: {
  name: string;
  onOpen: () => void;
  userId: string;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button size="icon-sm" variant="ghost" />}>
        <MoreHorizontalIcon />
        <span className="sr-only">Actions for {name}</span>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-44">
        <DropdownMenuGroup>
          <DropdownMenuItem onClick={onOpen}>
            <EyeIcon />
            View details
          </DropdownMenuItem>
          <DropdownMenuItem
            onClick={async () => {
              try {
                await navigator.clipboard.writeText(userId);
              } catch {
                // Insecure context or permission denied; nothing to undo.
              }
            }}
          >
            <CopyIcon />
            Copy user ID
          </DropdownMenuItem>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import { Button } from "@keystoneui/react/button";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@keystoneui/react/input-group";
import {
  Download as DownloadIcon,
  Search as SearchIcon,
  X as XIcon,
} from "lucide-react";
import {
  addableKeys,
  defaultDirection,
  directionLabel,
  filterDef,
  hasActiveFilters,
  SORT_KEYS,
  toUsersCsv,
  visibleKeys,
} from "./admin-filters";
import { AdminFiltersDrawer } from "./admin-filters-drawer";
import { ColumnsMenu } from "./columns-menu";
import { downloadCsv } from "./csv";
import { AddFilterMenu, usePillRow } from "./filter-pills";
import { SortMenu } from "./sort-menu";
import type { UserColumnId, UsersTableState } from "./use-users-table";
import { UserFilterPill } from "./user-filter-pills";

/**
 * The users toolbar: the payments toolbar's layout over the users vocabulary.
 *
 * Search, one self-describing pill per filter, `+ Add filter`, Clear all; at
 * the far end Columns, Export and Sort. Below `sm`, search and a Filters
 * drawer. See `AdminPaymentsToolbar` for the reasoning — the point of this
 * file is that there is none of its own to give.
 */
export function AdminUsersToolbar({
  columns,
  table,
}: {
  columns: readonly { id: UserColumnId; label: string }[];
  table: UsersTableState;
}) {
  // One export, the same rows wherever it is asked for: every filtered and
  // sorted row, not the page — and off while a request is in flight, or it
  // would write the rows the last query returned.
  const exportCsv = () =>
    downloadCsv("users.csv", toUsersCsv(table.result.all));
  const exportDisabled = table.loading || table.result.total === 0;
  const { added, filters, patchFilters } = table;
  const row = usePillRow({
    onAdd: table.addFilter,
    onRemove: table.removeFilter,
  });

  return (
    <div className="flex flex-wrap items-center gap-2">
      {/* A floor on the field's width, so a full row wraps its right-hand
          group onto a second line rather than crushing search to a stub. */}
      <InputGroup className="min-w-0 flex-1 sm:min-w-56 sm:max-w-xs" size="sm">
        <InputGroupAddon align="inline-start">
          <SearchIcon />
        </InputGroupAddon>
        <InputGroupInput
          aria-label="Search users"
          onChange={(event) => patchFilters({ search: event.target.value })}
          placeholder="Search name or email…"
          type="search"
          value={filters.search}
        />
      </InputGroup>

      <div
        className="hidden flex-wrap items-center gap-2 sm:flex"
        ref={row.rowRef}
      >
        {visibleKeys(filters, added).map((key) => (
          <UserFilterPill
            autoOpen={key === row.opening}
            filters={filters}
            key={key}
            onChange={patchFilters}
            onPin={table.addFilter}
            onRemove={row.remove}
            pillKey={key}
          />
        ))}

        <AddFilterMenu
          items={addableKeys(filters, added).map((key) => ({
            key,
            label: filterDef(key).label,
          }))}
          onAdd={row.add}
        />

        {hasActiveFilters(filters) && (
          <Button
            className="text-muted-foreground hover:text-foreground"
            onClick={table.clearFilters}
            size="sm"
            variant="ghost"
          >
            <XIcon />
            Clear all
          </Button>
        )}
      </div>

      <div className="hidden shrink-0 items-center gap-2 sm:ml-auto sm:flex">
        <ColumnsMenu
          columns={columns}
          hidden={table.hiddenColumns}
          onToggle={table.toggleColumn}
        />
        <Button
          disabled={exportDisabled}
          onClick={exportCsv}
          size="sm"
          variant="outline"
        >
          <DownloadIcon />
          Export
        </Button>
        <SortMenu
          defaultDirection={defaultDirection}
          directionLabel={directionLabel}
          keys={SORT_KEYS}
          onSortChange={table.setSort}
          sort={table.sort}
        />
      </div>

      <div className="shrink-0 sm:hidden">
        <AdminFiltersDrawer
          filters={filters}
          onChange={patchFilters}
          onSortChange={table.setSort}
          sort={table.sort}
          view={{
            columns,
            exportDisabled,
            hiddenColumns: table.hiddenColumns,
            onExport: exportCsv,
            onToggleColumn: table.toggleColumn,
            rowCount: table.result.total,
          }}
        />
      </div>
    </div>
  );
}

"use client";

import { Avatar, AvatarFallback } from "@keystoneui/react/avatar";
import { Badge } from "@keystoneui/react/badge";
import { Button } from "@keystoneui/react/button";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@keystoneui/react/card";
import { CopyButton } from "@keystoneui/react/copy-button";
import {
  DescriptionList,
  DescriptionListDetails,
  DescriptionListItem,
  DescriptionListTerm,
} from "@keystoneui/react/description-list";
import {
  Archive as ArchiveIcon,
  ArrowLeft as ArrowLeftIcon,
  Pencil as PencilIcon,
} from "lucide-react";
import type { ReactNode } from "react";

import { STATUS_VARIANT } from "./admin-filters";
import { statusLabels, type User } from "./mock-users";

interface AdminUserDetailProps {
  /** The user who sent the invite, resolved from `user.invitedBy`. */
  inviter: User | null;
  onBack: () => void;
  onOpenUser: (id: string) => void;
  user: User;
}

/**
 * A read-only record view.
 *
 * Three sections of label/value pairs in a `DescriptionList`, which is the
 * `dl`/`dt`/`dd` this is semantically — not a table, and not a form. The
 * `stacked` orientation puts each label above its value; the default row
 * layout right-aligns values against their labels, which reads as a summary
 * rather than a record.
 *
 * Values that identify something get `font-mono` and a `CopyButton`, because
 * an id exists to be pasted somewhere else. Enum values get a `Badge` so they
 * read the same here as they do in the table.
 */
export function AdminUserDetail({
  inviter,
  onBack,
  onOpenUser,
  user,
}: AdminUserDetailProps) {
  const initials = user.name
    .split(" ")
    .map((part) => part[0])
    .join("");

  return (
    <div className="flex w-full flex-col gap-6">
      {/* Full width with the actions at the far edge, while the card below is
          capped — so the buttons reach the container without the record's two
          columns drifting apart on a wide screen. Wraps, because the name, its
          badge and two labelled actions do not share a line on a phone. */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex min-w-0 items-center gap-3">
          <Button
            aria-label="Back to users"
            onClick={onBack}
            size="icon-sm"
            variant="ghost"
          >
            <ArrowLeftIcon />
          </Button>
          <Avatar size="sm">
            <AvatarFallback>{initials}</AvatarFallback>
          </Avatar>
          <h2 className="min-w-0 truncate font-semibold text-lg">
            {user.name}
          </h2>
          <Badge variant={STATUS_VARIANT[user.status]}>
            {statusLabels[user.status]}
          </Badge>
        </div>

        {/* Same 32px tier as the back button, so the header sits on one rung
            of the control ladder. */}
        <div className="flex shrink-0 items-center gap-2">
          <Button size="sm" variant="outline">
            <PencilIcon />
            Edit user
          </Button>
          <Button size="sm" variant="outline">
            <ArchiveIcon />
            Archive user
          </Button>
        </div>
      </div>

      {/* `pb-0` because the sections carry the bottom padding; the top stays
          the card's own, which is also what centres the header — CardHeader
          supplies its own bottom padding when it has a `border-b`, so setting
          `py-*` here would make it top-light. */}
      <Card className="max-w-4xl gap-0 pb-0">
        <CardHeader className="border-border border-b">
          <CardTitle className="text-base">User information</CardTitle>
        </CardHeader>
        {/* The card's own padding is zeroed so each section carries it, which
            lets the rules between them run the full width of the card rather
            than stopping short of its edges. */}
        <CardContent className="flex flex-col p-0">
          <Section title="Identity">
            <Pair term="User ID">
              <Mono value={user.id} />
            </Pair>
            <Pair term="Name">{user.name}</Pair>
            <Pair term="Email">
              <Mono value={user.email} />
            </Pair>
          </Section>

          <Section title="Access">
            <Pair term="Role">
              <Badge variant="outline">{user.role}</Badge>
            </Pair>
            <Pair term="Status">
              <Badge variant={STATUS_VARIANT[user.status]}>
                {statusLabels[user.status]}
              </Badge>
            </Pair>
            <Pair term="Seats">{user.seats}</Pair>
            <Pair term="Two-factor">
              {user.twoFactor ? "Enabled" : "Not enabled"}
            </Pair>
          </Section>

          <Section title="Activity">
            <Pair term="Created">{user.createdAt}</Pair>
            <Pair term="Last sign-in">{user.lastSignIn}</Pair>
            <Pair term="Last active">{user.lastActive}</Pair>
            {/* The founding account has no inviter. Rendering the dash here
                rather than omitting the row keeps the grid aligned and says
                "nothing" rather than leaving the reader to wonder. */}
            <Pair term="Invited by">
              {inviter ? (
                <button
                  className="cursor-pointer rounded-sm text-left hover:underline focus-visible:outline-2 focus-visible:outline-ring/50 focus-visible:outline-offset-2"
                  onClick={() => onOpenUser(inviter.id)}
                  type="button"
                >
                  {inviter.name}
                </button>
              ) : (
                <Empty />
              )}
            </Pair>
          </Section>
        </CardContent>
      </Card>
    </div>
  );
}

function Section({ children, title }: { children: ReactNode; title: string }) {
  return (
    <section className="flex flex-col gap-4 border-border border-t px-6 py-5 first:border-t-0">
      <h3 className="font-semibold text-foreground text-sm">{title}</h3>
      {/* The grid lives here rather than behind a `columns` prop: it is four
          classes on the element we already style, and it is written once for
          every section. */}
      <DescriptionList
        className="grid grid-cols-1 gap-x-8 gap-y-6 sm:grid-cols-2"
        orientation="stacked"
      >
        {children}
      </DescriptionList>
    </section>
  );
}

